import { Component, OnInit } from '@angular/core';
import { CreateSecurity, Issuer, SecuritiesService, TypeSecurity } from '../securities.service';
import { Router } from '@angular/router';
import { FormBuilder, FormGroup, Validators } from '@angular/forms';

@Component({
  selector: 'app-add-security',
  templateUrl: './add-security.component.html',
  styleUrls: ['./add-security.component.css']
})
export class AddSecurityComponent implements OnInit {
  addForm!: FormGroup
  types: TypeSecurity[] = [];
  issuers: Issuer[] = [];
  successMessage: string | null = null;
  errorMessage: string | null = null;

  constructor(private fb: FormBuilder, private securitiesService: SecuritiesService, private router: Router) { }

  ngOnInit(): void {
    this.addForm = this.fb.group({
      isin: ['', [Validators.required, Validators.maxLength(12)]],
      code: ['', [Validators.required, Validators.maxLength(50)]],
      totalNumShares: [0, [Validators.required, Validators.min(1)]],
      typeSecurityId: [null, Validators.required],
      issuerId: [null, Validators.required]
    });

    this.securitiesService.getTypes().subscribe(types => this.types = types);
    this.securitiesService.getIssuers().subscribe(issuers => this.issuers = issuers);
  }

  onSubmit() {
    if (this.addForm.invalid) return;

    const security: CreateSecurity = this.addForm.value;
    this.securitiesService.addSecurity(security).subscribe({
      next: () => {
        this.successMessage = 'Security added successfully!';
        this.errorMessage = '';
        this.addForm.reset();
        this.router.navigate(['/securities'], 2000);
      },
      error: (err) => {
        this.errorMessage = err?.error?.message || 'Error adding security';
        this.successMessage = '';
      }
    });
  }
}
<div class="container mt-4">
  <h2>Add New Security</h2>

  <form [formGroup]="addForm" (ngSubmit)="onSubmit()">

    <div class="mb-3">
      <label for="isin" class="form-label">ISIN</label>
      <input type="text" id="isin" class="form-control" formControlName="isin">
      <div *ngIf="addForm.get('isin')?.invalid && addForm.get('isin')?.touched" class="text-danger">
        ISIN is required and max 12 characters
      </div>
    </div>

    <div class="mb-3">
      <label for="code" class="form-label">Code</label>
      <input type="text" id="code" class="form-control" formControlName="code">
      <div *ngIf="addForm.get('code')?.invalid && addForm.get('code')?.touched" class="text-danger">
        Code is required and max 50 characters
      </div>
    </div>

    <div class="mb-3">
      <label for="totalNumShares" class="form-label">Total Shares</label>
      <input type="number" id="totalNumShares" class="form-control" formControlName="totalNumShares">
      <div *ngIf="addForm.get('totalNumShares')?.invalid && addForm.get('totalNumShares')?.touched" class="text-danger">
        Total shares must be at least 1
      </div>
    </div>

    <div class="mb-3">
      <label for="typeSecurityId" class="form-label">Type of Security</label>
      <select id="typeSecurityId" class="form-select" formControlName="typeSecurityId">
        <option value="" disabled>Select type</option>
        <option *ngFor="let type of types" [value]="type.id">{{ type.name }}</option>
      </select>
      <div *ngIf="addForm.get('typeSecurityId')?.invalid && addForm.get('typeSecurityId')?.touched" class="text-danger">
        Please select a type
      </div>
    </div>

    <div class="mb-3">
      <label for="issuerId" class="form-label">Issuer</label>
      <select id="issuerId" class="form-select" formControlName="issuerId">
        <option value="" disabled>Select issuer</option>
        <option *ngFor="let issuer of issuers" [value]="issuer.id">{{ issuer.name }}</option>
      </select>
      <div *ngIf="addForm.get('issuerId')?.invalid && addForm.get('issuerId')?.touched" class="text-danger">
        Please select an issuer
      </div>
    </div>

    <button class="btn btn-primary" type="submit" [disabled]="addForm.invalid">Add Security</button>

  </form>

  <div *ngIf="successMessage" class="alert alert-success mt-3">{{ successMessage }}</div>
  <div *ngIf="errorMessage" class="alert alert-danger mt-3">{{ errorMessage }}</div>
</div>
